<?php

namespace App\Data\Shared;

use Spatie\LaravelData\Data;
use Spatie\TypeScriptTransformer\Attributes\TypeScript;

/**
 * Where the dashboard opens its websocket (the public Reverb key and address, never the secret). Read at runtime because the
 * Reverb keys are generated by the install, after the frontend bundle of a Docker image was built.
 */
#[TypeScript]
class RealtimeEndpointData extends Data
{
    public function __construct(
        public string $key,
        public string $host,
        public int $port,
        public string $scheme,
    ) {}
}
